/* ELO API Playground CodeMirror 5 modes for Go, PHP and Java.
 * Kept local with the other pinned vendor assets. The tokenizer deliberately
 * covers the language surface shown in the playground (comments, strings,
 * numbers, keywords and types) without loading code from a CDN. */
(function (CodeMirror) {
  "use strict";
  if (!CodeMirror) return;
  var definitions = {
    go: {
      keywords: "break default func interface select case defer go map struct chan else goto package switch const fallthrough if range type continue for import return var",
      types: "any bool byte comparable complex64 complex128 error float32 float64 int int8 int16 int32 int64 rune string uint uint8 uint16 uint32 uint64 uintptr",
      atoms: "true false iota nil"
    },
    php: {
      keywords: "abstract and array as break callable case catch class clone const continue declare default do echo else elseif empty enddeclare endfor endforeach endif endswitch endwhile enum eval exit extends final finally fn for foreach function global goto if implements include include_once instanceof insteadof interface isset list match namespace new or print private protected public readonly require require_once return static switch throw trait try unset use var while xor yield",
      types: "bool float int iterable mixed never null object resource self string void parent static",
      atoms: "true false null"
    },
    java: {
      keywords: "abstract assert break case catch class continue default do else enum extends final finally for if implements import instanceof interface native new package private protected public return sealed static strictfp super switch synchronized this throw throws transient try volatile while",
      types: "boolean byte char double float int long short void var record",
      atoms: "true false null"
    }
  };
  function words(source) {
    var out = Object.create(null);
    source.split(" ").forEach(function (word) { out[word] = true; });
    return out;
  }
  function define(name) {
    var definition = definitions[name];
    var keywords = words(definition.keywords), types = words(definition.types), atoms = words(definition.atoms);
    CodeMirror.defineMode(name, function () {
      return {
        startState: function () { return { block: false }; },
        token: function (stream, state) {
          if (state.block) {
            if (stream.skipTo("*/")) { stream.match("*/"); state.block = false; }
            else stream.skipToEnd();
            return "comment";
          }
          if (stream.eatSpace()) return null;
          if (stream.match("/*")) { state.block = true; return "comment"; }
          if (stream.match("//") || (name === "php" && stream.match("#"))) { stream.skipToEnd(); return "comment"; }
          if (stream.match(/^\$[A-Za-z_][\w]*/)) return "variable-2";
          var quote = stream.peek();
          if (quote === '"' || quote === "'" || quote === "`") {
            stream.next();
            var escaped = false, ch;
            while ((ch = stream.next()) != null) {
              if (ch === quote && !escaped) break;
              escaped = ch === "\\" && !escaped;
              if (ch !== "\\") escaped = false;
            }
            return "string";
          }
          if (stream.match(/^\d+(?:\.\d+)?(?:[eE][+-]?\d+)?[fLd]?/)) return "number";
          if (stream.match(/^[A-Za-z_][\w]*/)) {
            var word = stream.current();
            if (keywords[word]) return "keyword";
            if (types[word]) return "type";
            if (atoms[word]) return "atom";
            if (/^[A-Z]/.test(word)) return "type";
            return "variable";
          }
          stream.next();
          return null;
        },
        lineComment: name === "php" ? "//" : "//",
        blockCommentStart: "/*",
        blockCommentEnd: "*/"
      };
    });
    CodeMirror.defineMIME("text/x-" + name, name);
  }
  Object.keys(definitions).forEach(define);
}(window.CodeMirror));
